        // activation (FR7): the same rule link rows get from the shared
        // enlarged-surface hook below.
        if (hasInteractiveAncestor(e.target as Element, e.currentTarget)) {
          return;
        }
        if (onClick != null) {
          onClick(e);
        } else if (hasChildren && onToggle != null) {
          onToggle(id);
        }
