 *   <div
 *     ref={containerRef}
 *     onClick={onClick}
 *     onMouseUp={onMouseUp}
 *     onPointerDown={onPointerDown}>
 *     <p>Click anywhere on this card</p>
 *     <button onClick={() => alert('button')}>Nested button</button>
 *   </div>
