export function useClickableContainerProxy({
  containerRef,
  interactiveRef,
  onClick: onClickProp,
  href,
  target,
  disabled = false,
}: UseClickableContainerOptions): ClickableContainerResult {
  const onClick = useCallback(
    (event: MouseEvent<HTMLElement>) => {
      if (disabled) {
        return;
      }

      const containerEl = containerRef.current;
      if (!containerEl) {
        return;
      }

      if (hasTextSelection(containerEl)) {
        return;
      }

      const eventTarget = event.target;
      if (!(eventTarget instanceof Element)) {
        return;
      }

      if (
        eventTarget !== event.currentTarget &&
        hasInteractiveAncestor(eventTarget, containerEl)
      ) {
        return;
      }

      onClickProp?.(event);
      if (event.defaultPrevented) {
        return;
      }

      // React DOM checks the hrefs that it writes, but nothing below passes
      // through React. So the shared navigation rule decides once, before the
      // target, a modifier key, or the delegated anchor picks a sink. A
      // blocked href does not navigate, but the click handler above still ran.
      if (href != null && isSafeUrl(href)) {
        const shouldOpenNewTab =
          target === '_blank' || event.ctrlKey || event.metaKey;
        if (shouldOpenNewTab) {
          window.open(href, '_blank', 'noopener');
        } else if (interactiveRef?.current) {
          // Proxy click to the sr-only link so the framework link component
          // handles navigation (client-side transitions in Next.js, etc.).
          interactiveRef.current.click();
        } else {
          // eslint-disable-next-line react-compiler/react-compiler -- browser navigation API
          window.location.href = href;
        }
      }

      // Proxy click to the interactive ref if no explicit handler
      if (href == null && onClickProp == null && interactiveRef?.current) {
        const clickEvent = new MouseEvent('click', {
          bubbles: event.bubbles,
          cancelable: event.cancelable,
          ctrlKey: event.ctrlKey,
          metaKey: event.metaKey,
          shiftKey: event.shiftKey,
          altKey: event.altKey,
          button: event.button,
        });
        interactiveRef.current.dispatchEvent(clickEvent);
        event.stopPropagation();
      }
    },
    [containerRef, interactiveRef, onClickProp, href, target, disabled],
  );

  const onMouseUp = useCallback(
    (event: MouseEvent<HTMLElement>) => {
      if (disabled) {
        return;
      }

      const containerEl = containerRef.current;
      if (!containerEl) {
        return;
      }

      const eventTarget = event.target;
      if (!(eventTarget instanceof Element)) {
        return;
      }

      // Middle-click on href opens in new tab (same scheme rule as onClick —
      // this navigation never passes through React either).
      const isMiddleClick = event.button === 1;
      if (
        isMiddleClick &&
        href != null &&
        isSafeUrl(href) &&
        (eventTarget === event.currentTarget ||
          !hasInteractiveAncestor(eventTarget, containerEl))
      ) {
        window.open(href, '_blank', 'noopener');
      }
    },
    [containerRef, href, disabled],
  );

  // The press-state counterpart of onClick's rule, for touch: a finger press
  // that would not activate the container shows no press on it. A mouse or
  // pen press keeps its `:active` paint.
  const onPointerDown = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      if (disabled) {
        return;
      }
      cancelNestedTouchPress(
        event,
        containerRef.current,
        interactiveRef?.current ?? null,
      );
    },
    [containerRef, interactiveRef, disabled],
  );

  return {onClick, onMouseUp, onPointerDown};
}

