function springAtTempo(
  spring: SpringDescription,
  tempo: number,
): SpringDescription {
  let byTempo = springsAtTempo.get(spring);
  if (byTempo == null) {
    byTempo = new Map();
    springsAtTempo.set(spring, byTempo);
