          group[key] = leaf;
        }
      }
      const role: MotionRole = {
        id: roleId,
        kind,
        variable: motionRoleVariable(roleId),
        value: leaf,
      };
      rolesById.set(roleId, role);
      if (typeof leaf === 'object') {
        roleOfLeaf.set(leaf, role);
      }
    }
