  doc: Document,
  {ms, points}: ResolvedTiming,
  easing: string,
): MotionCurve | null {
  if (ms == null || ms <= 0) {
    return null;
  }
  if (points != null) {
    return easedProgress(ms / 1000, cubicBezier(points));
  }
  const ease = browserEasing(doc, easing);
  return ease == null ? null : easedProgress(ms / 1000, ease, {jumps: true});
